//! **Expected to fail** against reference `zsh -fc` on substantive behavior:
//! each test compares **exit code and stdout** between `zshrs --zsh -fc` and
//! `zsh -fc`. **Stderr is ignored** for pass/fail so diagnostics that differ only
//! in shell name / path / minor wording still count as matched.
//!
//! When `zsh` is missing, tests return early.
//!
//! **Coverage**: language surface under `zsh -fc` / `zshrs --zsh -fc` (state, options,
//! parameters, builtins, expansion, redirections, history, ZLE-adjacent, jobs, plus
//! larger scripted corpora, `corpus_dash_fc_surface_extra`, `corpus_dash_fc_compounds_misc`,
//! `corpus_dash_fc_control_flow`, `corpus_dash_fc_params_redir`, `corpus_dash_fc_bulk_a`,
//! `corpus_dash_fc_bulk_b`, `corpus_dash_fc_bulk_c`, `corpus_dash_fc_bulk_d`,
//! `corpus_dash_fc_bulk_e`, `corpus_dash_fc_bulk_f`, `corpus_dash_fc_bulk_g`,
//! `corpus_dash_fc_bulk_h`, `corpus_dash_fc_bulk_i`, `corpus_dash_fc_bulk_j`, `corpus_dash_fc_bulk_k`, `corpus_dash_fc_bulk_l`,
//! `corpus_dash_fc_bulk_m`, `corpus_dash_fc_bulk_n`, `corpus_dash_fc_bulk_o`, `corpus_dash_fc_bulk_p`,
//! `corpus_dash_fc_bulk_q`, `corpus_dash_fc_bulk_r`, `corpus_dash_fc_bulk_s`, `corpus_dash_fc_bulk_t`, `corpus_dash_fc_bulk_u`, `corpus_dash_fc_bulk_v`,
//! `corpus_dash_fc_bulk_w` … `corpus_dash_fc_bulk_ak`, rounds 1–800: `corpus_dash_fc_bulk_al` … `corpus_dash_fc_bulk_ahr` (48 zsh-probed `-fc` pins/round; `al`=1, `eg`=100, `ic`=200, `ly`=300, `pu`=400, `tq`=500, `xm`=600, `aaa`=601, `adv`=700, `ahr`=800). Pass/fail is **stdout + exit** only (see `assert_parity`).

#![allow(non_snake_case)]

use std::path::PathBuf;
use std::process::Command;

fn zshrs_bin() -> PathBuf {
    if let Ok(p) = std::env::var("CARGO_BIN_EXE_zshrs") {
        return PathBuf::from(p);
    }
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("target")
        .join("debug")
        .join("zshrs")
}

fn zsh_path() -> &'static str {
    use std::path::Path;
    if Path::new("/opt/homebrew/bin/zsh").exists() {
        "/opt/homebrew/bin/zsh"
    } else if Path::new("/usr/local/bin/zsh").exists() {
        "/usr/local/bin/zsh"
    } else {
        "/bin/zsh"
    }
}

fn zsh_available() -> bool {
    Command::new(zsh_path())
        .arg("--version")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

struct ShellResult {
    stdout: String,
    stderr: String,
    exit: i32,
}

fn run_zsh(script: &str) -> ShellResult {
    let out = Command::new(zsh_path())
        .args(["-fc", script])
        .output()
        .expect("invoke zsh");
    ShellResult {
        stdout: String::from_utf8_lossy(&out.stdout).into_owned(),
        stderr: String::from_utf8_lossy(&out.stderr).into_owned(),
        exit: out.status.code().unwrap_or(-1),
    }
}

fn run_zshrs(script: &str) -> ShellResult {
    let out = Command::new(zshrs_bin())
        .args(["--zsh", "-fc", script])
        .env_remove("ZSHRS_CACHE")
        .output()
        .expect("invoke zshrs");
    ShellResult {
        stdout: String::from_utf8_lossy(&out.stdout).into_owned(),
        stderr: String::from_utf8_lossy(&out.stderr).into_owned(),
        exit: out.status.code().unwrap_or(-1),
    }
}

/// **Exit code + stdout** only; stderr is context in the panic message.
fn assert_parity(script: &str, label: &str) {
    if !zsh_available() {
        return;
    }
    let z = run_zsh(script);
    let r = run_zshrs(script);
    if z.stdout != r.stdout || z.exit != r.exit {
        panic!(
            "parity gap (exit + stdout): {label}\nscript:\n{script}\n\
--- zsh stdout ---\n{:?}\n--- zshrs stdout ---\n{:?}\n\
--- zsh stderr (context) ---\n{:?}\n--- zshrs stderr (context) ---\n{:?}\n\
--- exit zsh={} zshrs={}",
            z.stdout, r.stdout, z.stderr, r.stderr, z.exit, r.exit
        );
    }
}

/// Expands to one `#[test] fn` per `name => (label, script)` row (label + script: raw strings).
macro_rules! parity_gap_tests {
    ($($name:ident => ($label:literal, $script:expr);)+) => {
        $(
            #[test]
            fn $name() {
                assert_parity($script, $label);
            }
        )+
    };
}

mod context_and_state {
    use super::*;

    parity_gap_tests! {
        zsh_eval_context_matches_reference => (r#"ZSH_EVAL_CONTEXT"#, r#"echo $ZSH_EVAL_CONTEXT"#);
        plus_special_assoc_table_flags_match => (r#"$+commands … $+zsh_scheduled_events"#, r#"print $+commands $+functions $+aliases $+history $+terminfo $+parameters $+options $+builtins $+galiases $+dis_aliases $+dis_builtins $+usergroups $+widgets $+dis_functions $+dirstack $+functrace $+module_path $+patchars $+ZPFX $+pipestatus $+zsh_scheduled_events"#);
        builtins_table_element_count => (r#"${#builtins}"#, r#"print ${#builtins}"#);
        zsh_execution_string_set_under_dash_c => (r#"ZSH_EXECUTION_STRING"#, r#"print -r "$ZSH_EXECUTION_STRING""#);
        // GLOB_ASSIGN: only a literal UNQUOTED glob pattern in the RHS is
        // globbed (Src/exec.c:2554). A double-quoted value with a `*` is
        // assigned verbatim — NOT globbed, NO "no match" error. Regression
        // pin: zshrs used to re-tokenize the dequoted value and glob it,
        // flooding startup (zpwr's `x="zstyle ':completion:*' ..."` lines)
        // with `no match` under `setopt cshnullglob`.
        glob_assign_double_quoted_value_not_globbed =>
            (r#"setopt glob_assign; x="/no/such/dir/*""#,
             r#"setopt glob_assign; x="/no/such/dir/*"; print -r -- "[$x]""#);
        glob_assign_single_quoted_value_not_globbed =>
            (r#"setopt glob_assign; x='/no/such/dir/*'"#,
             r#"setopt glob_assign; x='/no/such/dir/*'; print -r -- "[$x]""#);
        glob_assign_param_expansion_value_not_globbed =>
            (r#"setopt glob_assign; foo=/no/such/*; x=$foo"#,
             r#"setopt glob_assign; foo="/no/such/*"; x=$foo; print -r -- "[$x]""#);
        glob_assign_cmdsubst_value_not_globbed =>
            (r#"setopt glob_assign; x=$(...glob str...)"#,
             r#"setopt glob_assign; x=$(print -r -- "/no/such/*"); print -r -- "[$x]""#);
        glob_assign_cshnullglob_quoted_glob_no_error =>
            (r#"cshnullglob quoted glob assign, then empty cmd"#,
             r#"setopt glob_assign cshnullglob; x="zstyle ':completion:*' completer _foo"; : ; print done"#);
        glob_assign_unquoted_literal_glob_expands =>
            (r#"setopt glob_assign; x=$d/* (unquoted literal glob expands)"#,
             r#"d=/tmp/zshrs_gatest_$$; mkdir -p $d; touch $d/aa $d/bb; setopt glob_assign; x=$d/*; print -r -- "${(o)x:t}"; rm -rf $d"#);
        glob_assign_off_default_no_glob =>
            (r#"x=/no/such/* with glob_assign OFF assigns literal"#,
             r#"unsetopt glob_assign; setopt nonomatch; x=/no/such/*; print -r -- "[$x]""#);
        // printf `%c`/`%q` honor the `0` flag (zero-pad); `%s` does not
        // (Src/builtin.c: %c/%q go through print_val, %s inline space-pads).
        // Fuzz-discovered; was space-padding `%0Nc`/`%0Nq`.
        printf_zero_flag_c_zero_pads =>
            (r#"printf %04c x -> 000x"#, r#"printf '%04c|%09.1c|' x 007"#);
        printf_zero_flag_q_zero_pads =>
            (r#"printf %04q a -> 000a"#, r#"printf '%04q|%-04c|' a x"#);
        printf_zero_flag_s_space_pads =>
            (r#"printf %04s ab -> '  ab' (s NOT zero-padded)"#, r#"printf '%04s|%06.3s|' ab abcdef"#);
        // printf `%e`/`%E`/`%g` high-precision must be EXACT (correctly-rounded),
        // not the binary error from `n / 10^exp`. Fuzz-discovered:
        // `%.27e 37` printed `3.7000…0177635683940e+01` instead of `…000e+01`.
        printf_e_high_precision_exact =>
            (r#"printf %.27e 37 -> exact trailing zeros"#, r#"printf '%.27e|%.31e|' 37 37"#);
        printf_g_high_precision_exact =>
            (r#"printf %.20g 37 -> exact"#, r#"printf '%.20g|%.3e|' 37 9.9999"#);
        // `%` conversion carrying a precision `*` is an invalid directive even
        // when the `*` has no matching arg (zsh: exit 1, stop). zshrs used to
        // print `%` and continue because the arg-less `*` emitted nothing.
        // Fuzz-discovered.
        printf_star_prec_percent_invalid_no_arg =>
            (r#"printf '%-3e%.*%|' -> invalid directive, exit 1"#,
             r#"printf '%-3e%.*%|'"#);
        printf_star_prec_still_works =>
            (r#"printf '%.*d' 3 42 -> '042'; no-arg -> default"#,
             r#"printf '%.*d|' 3 42; printf '%.*d|' 42"#);
        // KSHARRAYS: a BARE array ref with a param flag/modifier folds only
        // element 0 (`${(o)a}` → `${a[0]}`), but an explicit `[@]`/`[*]` splat
        // keeps the whole array. The compiler used to strip `[@]` for flag-
        // params (parse_zsh_flag), collapsing both to `${(o)a}`. Fuzz-discovered.
        ksh_arrays_bare_flag_uses_element0 =>
            (r#"setopt ksh_arrays; ${(o)a}/${(u)a}/${(U)a}/${(j)a}/${a:u} -> element 0"#,
             r#"setopt ksh_arrays; a=(c a b); print -r -- ${(o)a} ${(u)a} ${(U)a} ${(j:-:)a} ${a:u}"#);
        ksh_arrays_at_splat_keeps_whole =>
            (r#"setopt ksh_arrays; ${(o)a[@]} keeps whole array"#,
             r#"setopt ksh_arrays; a=(c a b); print -r -- "${(o)a[@]}|${(U)a[*]}|${(j:-:)a[@]}""#);
        ksh_arrays_off_flag_whole_array =>
            (r#"no ksh_arrays: ${(o)a} and ${(o)a[@]} both whole array"#,
             r#"a=(c a b); print -r -- "${(o)a}|${(o)a[@]}""#);
        // (Q) unquote inside `"…"`: backslash is removed only before $ \ " `
        // (lex.c:1501). Before any other char (`\t`, `\n`) the backslash stays
        // LITERAL. zshrs stripped it unconditionally → `"a\tb"` gave `atb`.
        q_unquote_dquote_keeps_literal_backslash =>
            (r#"${(Q)} of a "…"-quoted value keeps \t/\n literal, strips \$ \" \\"#,
             r#"x='"a\tb\nc\"d\$e\\f"'; print -r -- ${(Q)x}"#);
        q_unquote_squote_keeps_all_backslash =>
            (r#"${(Q)} of a '…'-quoted value keeps every backslash literal"#,
             r#"x="'a\tb\nc'"; print -r -- ${(Q)x}"#);
        q_unquote_bare_strips_backslash =>
            (r#"${(Q)} of a bare (unquoted) value strips backslash before any char"#,
             r#"x='a\tb\nc'; print -r -- ${(Q)x}"#);
        // Flag order: `(#)` numeric→char conversion runs BEFORE case flags
        // (U/L/C) — subst.c:3811 (evalchar) precedes subst.c:3948 (casmod). So
        // `${(#U)x}` with x=97 is `#`→'a'→U→'A', not U→"97"→char→'a'. zshrs
        // applied case first, yielding the lowercase char. Fuzz-discovered.
        hash_flag_evalchar_before_case_mod =>
            (r#"${(#U)97}->A ${(#C)97}->A ${(#L)65}->a: (#) char-conv precedes case"#,
             r#"x=97; y=65; print -r -- "${(#U)x}|${(#C)x}|${(#L)y}""#);
        // Flag order: positive `q` quote runs BEFORE `(V)` visible (subst.c:4041
        // vs 4160). q yields printable ASCII (`$'\t'`), so V (nicechar) on it is
        // a no-op — `${(V#q)empty}` is `$'\0'`, not V re-escaping to `\^@`.
        v_and_q_flag_order_q_before_visible =>
            (r#"${(V#q)empty}->$'\0' and ${(#qV)9}->$'\t': q precedes V, V is no-op"#,
             r#"empty=''; nine=9; print -r -- "${(V#q)empty}|${(#qV)nine}|${(Vq)empty}""#);
        // Combined (l) + (r) padding in one flag group: subst.c:949-1109 splits
        // the value at width/2, left-pads the first half to the l-width and
        // right-pads the second half to the r-width, then concatenates.
        // `${(l:5::-:r:8::+:)ab}` → `----ab+++++++` (split "a"|"b"), NOT a
        // sequential left-then-right on the whole string (`---ab+++`).
        combined_l_r_padding_splits_at_half =>
            (r#"${(l:5::-:r:8::+:)ab} -> ----ab+++++++ ; empty -> full l-fill+r-fill"#,
             r#"x=ab; e=''; print -r -- "${(l:5::-:r:8::+:)x}|${(l:6::.:r:4::_:)x}|${(l:10::-:r:5::+:)e}""#);
        // nocaseglob affects only FILENAME globbing (PAT_FILE); pattern matching
        // in [[ ]], case, ${arr:#pat}, ${s//pat} stays case-SENSITIVE. C resets
        // patglobflags (dropping GF_IGNCASE) for non-file patterns (pattern.c:568).
        nocaseglob_does_not_affect_conditional_match =>
            (r#"setopt nocaseglob: [[ ABC == abc ]] and ${(ABC):#abc} stay case-sensitive"#,
             r#"setopt nocaseglob; a=(ABC); [[ ABC == a*c ]] && m=Y || m=N; print -r -- "$m|${a:#abc}|${(M)a:#a*c}""#);
        // (g::) bare form uses getkeys==0: `\c` (GETKEY_BACKSLASH_C) and
        // `\C`/`^X` (GETKEY_EMACS/GETKEY_CTRL) stay LITERAL; only standard
        // escapes (\t \n) decode. The sub-flags (g:c:)/(g:e:)/(g:o:) enable the
        // gated escapes. zshrs decoded `\c` unconditionally (used the flagless
        // getkeystring), so ${(g::)$'\cb'} wrongly gave ^B.
        g_flag_default_keeps_c_escape_literal =>
            (r#"${(g::)$'\cb'} keeps \cb literal; ${(g::)$'a\tb'} decodes tab"#,
             r#"c=$'\cb'; t=$'a\tb'; print -rn -- "${(g::)c}|${(g::)t}"; echo"#);
        // After `exec 0<&-` closes fd 0, a `< FILE` redirect must reopen it:
        // open() returns fd 0 (lowest free), so `dup2(0,0)` is a no-op — the
        // code must NOT close new_fd (would re-close the file) and MUST clear
        // O_CLOEXEC (Rust's File::open sets it; a no-op dup2 doesn't clear it,
        // so exec'd children would lose the fd). Fixes gitstatus/p10k daemon
        // handshake hang (install read `< install.info` returned empty).
        closed_fd0_read_redirect_reopens =>
            (r#"exec 0<&-; then read < file (builtin) and head < file (external) see the file"#,
             r#"exec 0<&-; read a < /etc/passwd; b=$(head -1 < /etc/passwd); print -r -- "$a|$b""#);
    }
}

